n.exploreUrl:
@js:
var result = [];
var areas = ['韩国','日本','中国'];
var fulls = [{id:'4',name:'连载中'},{id:'1',name:'已完结'}];

// 默认全部
result.push({
  title: '最新更新',
  url: '/api/comic/index/lists,{"method":"POST","body":"area=9&tags=全部&full=3&page={{page}}"}',
  style: {layout_flexGrow: 1, layout_flexBasisPercent: 1}
});

// 按地区
for (var i = 0; i < areas.length; i++) {
  result.push({
    title: areas[i],
    url: '/api/comic/index/lists,{"method":"POST","body":"area=' + (i+1) + '&tags=全部&full=3&page={{page}}"}',
    style: {layout_flexGrow: 1, layout_flexBasisPercent: 0.25}
  });
}

// 按进度
for (var i = 0; i < fulls.length; i++) {
  result.push({
    title: fulls[i].name,
    url: '/api/comic/index/lists,{"method":"POST","body":"area=9&tags=全部&full=' + fulls[i].id + '&page={{page}}"}',
    style: {layout_flexGrow: 1, layout_flexBasisPercent: 0.25}
  });
}

// 组合
result.push({
  title: '韩国连载中',
  url: '/api/comic/index/lists,{"method":"POST","body":"area=1&tags=全部&full=4&page={{page}}"}'
});
result.push({
  title: '日本连载中',
  url: '/api/comic/index/lists,{"method":"POST","body":"area=2&tags=全部&full=4&page={{page}}"}'
});

JSON.stringify(result);

